 for(let i=0;i<5;i++){const a=makeUnit(-34+rand(-3,3),rand(-7,7),0,'worker',options.faction),b=makeUnit(main.x+rand(-3,3),main.z+rand(-5,5),1,'worker',main.faction);if(i>2)a.gatherKind=b.gatherKind='gas'}
