function openBuildingCatalog(){if(!game||game.over||game.paused||selected?.team!==myTeam())return;const list=$('#building-list');list.innerHTML='';for(const d of factionBuildings(game.faction)){const button=document.createElement('button');button.textContent=d.label+' · '+d.cost+'✦ '+d.gas+'◆ · '+d.time+'s';button.onclick=()=>startBuildingPlacement(d.id);list.append(button)}$('#building-catalog').hidden=false}
function startBuildingPlacement(kind){if(!game||game.over||game.paused)return;$('#building-catalog').hidden=true;placement.start(kind,selected?.x??camTarget.x,selected?.z??camTarget.z);tell('Escolha o local no terreno. Verde permite construir; vermelho indica bloqueio.')}
function constructAt(kind,x,z){if(!game||game.paused||game.over||(game.mode==='pvp'&&!game.online))return null;if(!fogs[myTeam()].canSee(x,z)){tell('Explore este local antes de construir.');return null}if(game.mode==='pvp'&&netRole==='guest'){sendCommand({kind:'placeBuilding',buildingKind:kind,x,z});return {requested:true}}return placeBuildingAt(kind,x,z,myTeam(),game.faction)}
