function refreshVegetation(){scenery?.setChunks([...terrainChunks.keys()].map(k=>{const [cx,cz]=k.split(',').map(Number);return {cx,cz}}),true);vegetation?.setChunks([...terrainChunks.keys()].map(k=>{const [cx,cz]=k.split(',').map(Number);return {cx,cz}}),true)}
