  if(u.type==='medic'&&u.cooldown<=0){const ally=units.find(a=>a.alive&&a.team===u.team&&a!==u&&a.hp<a.maxHp&&dist(a,u)<8);if(ally){ally.hp=Math.min(ally.maxHp,ally.hp+14);u.cooldown=1}}
