function populateMission(def){
 const enemyVariant={solar:game.encounterSeed%2?'veil':'solar',aether:game.encounterSeed%3?'aether':'silex',swarm:game.encounterSeed%2?'root':'swarm'};const factionFor=d=>d.team===1?(enemyVariant[d.faction||def.faction]||d.faction||def.faction):(d.faction||def.faction);
 if(!def)throw new Error('Missão desconhecida.');game.resources=[{...def.start.resources},{crystals:0,gas:0}];game.stats={kills:0,losses:0};campaignRun=new CampaignRuntime(def);
 const placeBuilding=d=>{const b=makeBuilding(d.x,d.z,d.team??0,factionFor(d),d.kind);b.missionTag=d.missionTag;return b};
 const placeUnit=d=>{const u=makeUnit(d.x,d.z,d.team??0,d.type,factionFor(d));u.missionTag=d.missionTag;if(u.type==='worker')u.gatherKind=u.id%3===0?'gas':'crystals';if(u.team===2||d.hold)u.hold=true;return u};
 placeBuilding(def.start.playerBase);def.enemyBuildings.forEach(placeBuilding);[...def.start.playerUnits,...jitterEnemyPositions(def,game.encounterSeed),...def.neutralUnits].forEach(placeUnit);
 for(const marker of def.markers){const group=objectGroup(marker.x,marker.z),ring=mesh(new THREE.RingGeometry(marker.radius-.25,marker.radius,48),new THREE.MeshBasicMaterial({color:0xffd18c,side:THREE.DoubleSide,transparent:true,opacity:.7,depthWrite:false}),group,0,.12,0);ring.rotation.x=-Math.PI/2;mesh(new THREE.OctahedronGeometry(.7),new THREE.MeshStandardMaterial({color:0xffd18c,emissive:0xffd18c,emissiveIntensity:.55}),group,0,2,0);missionMarkers.push({def:marker,group})}
 updateMissionHUD(campaignRun.objectives({units,buildings}));
}
function applyMissionEvents(events){for(const event of events){if(event.kind==='spawnWave'){const base=buildings.find(b=>b.alive&&b.team===0&&b.kind==='base');for(const d of event.units){const u=makeUnit(d.x,d.z,1,d.type,d.faction||'swarm');u.missionTag=d.missionTag;if(base){moveUnit(u,base.x,base.z);u.order='attackMove'}}tell('Uma nova onda inimiga se aproxima.')}if(event.kind==='rescue'){for(const id of event.ids){const u=getEntity(id);if(!u)continue;u.team=0;u.hold=false;u.target=null;u.targetEnemy=null;u.mediaBeacon?.material.color.setHex(0x51d6ff)}tell('Equipe resgatada: reforços sob seu comando.')}}}
function updateMissionHUD(objectives){const panel=$('#objective-panel');panel.hidden=!campaignRun;if(!campaignRun)return;$('#mission-title').textContent=campaignRun.def.label;const list=$('#objective-list');list.innerHTML='';for(const o of objectives){const row=document.createElement('li');row.className=o.done?'done':'';row.textContent=(o.done?'✓ ':'○ ')+o.label+' · '+Math.floor(o.current)+'/'+o.target;list.append(row)}}
function startMission(id){if(!canPlayMission(campaignProgress,id)&&!$('#training').checked){tell('Conclua a missão anterior para desbloquear esta fase.');return}const def=missionById(id);selectedMissionId=id;try{begin({mode:'campaign',missionId:id,training:$('#training').checked,map:def.map,faction:def.faction,seed:def.seed,difficulty:$('#difficulty').value})}catch(e){console.error(e);tell('Não foi possível iniciar a missão: '+e.message)}}
function finishMission(result){if(game.over)return;game.over=true;stopGameAudio();if(result==='victory'&&!game.training){campaignProgress=unlockProgress(campaignProgress,game.missionId);try{localStorage.setItem('spaceinvaders_campaign_v1',JSON.stringify(campaignProgress))}catch(e){}playSound('win')}const index=missions.findIndex(m=>m.id===game.missionId);$('#result-title').textContent=result==='victory'?'MISSÃO CONCLUÍDA':'MISSÃO ENCERRADA';$('#result-message').textContent=result==='victory'?'Objetivos cumpridos. A próxima operação está disponível.':'Seu núcleo ou uma unidade essencial foi perdida. Reorganize a estratégia e tente novamente.';$('#result-stats').textContent=Math.floor(game.elapsed)+' segundos · '+(game.stats?.kills||0)+' alvos destruídos · '+campaignProgress.completed.length+'/'+missions.length+' operações concluídas';$('#result-next').hidden=result!=='victory'||index===missions.length-1;if(result==='victory'&&index===missions.length-1)$('#result-message').textContent='Campanha concluída! Todas as 105 adaptações foram vencidas.';$('#debrief').hidden=false;renderCampaignMenu()}
function showMenu(){placement?.cancel();$('#building-catalog').hidden=true;screen.style.display='flex';$('#debrief').hidden=true;$('#objective-panel').hidden=true;if(socket)socket.close();stopGameAudio();game=null;campaignRun=null;renderCampaignMenu();battleHud?.update()}
function renderCampaignMenu(){const active=$('#mode').value==='campaign';$('#campaign-panel').hidden=!active;for(const id of ['seed','faction','map','difficulty'])$('#'+id).closest('label').hidden=active;for(const id of ['server','room'])$('#'+id).closest('label').hidden=$('#mode').value!=='pvp';$('#mode').closest('label').style.gridColumn=active?'1 / -1':'';$('#start').textContent=active?'INICIAR MISSÃO':'INICIAR OPERAÇÃO';const list=$('#mission-list');list.innerHTML='';for(const def of missions.filter(d=>!$('#mission-search').value||(d.label+' '+d.id).toLowerCase().includes($('#mission-search').value.toLowerCase()))){const button=document.createElement('button'),unlocked=canPlayMission(campaignProgress,def.id);button.dataset.missionId=def.id;button.textContent=(campaignProgress.completed.includes(def.id)?'✓ ':unlocked?'':'🔒 ')+def.label;button.disabled=!unlocked&&!$('#training').checked;button.style.backgroundImage='linear-gradient(90deg,#091a2be8,#091a2b8c),url("./campaign-maps/'+campaignGrids[def.id].name+'.png")';button.setAttribute('aria-pressed',String(def.id===selectedMissionId));button.onclick=()=>{selectedMissionId=def.id;renderCampaignMenu()};list.append(button)}const def=missionById(selectedMissionId)||missions[0];$('#mission-count').textContent=missions.length+' cenários · '+campaignProgress.completed.length+' concluídos';$('#briefing-title').textContent=def.label;$('#briefing-text').textContent=def.briefing;$('#briefing-objectives').innerHTML='';for(const objective of def.objectives){const li=document.createElement('li');li.textContent=objective.label;$('#briefing-objectives').append(li)}document.dispatchEvent(new Event('campaign-menu-updated'))}
$('#mode').addEventListener('change',renderCampaignMenu);$('#result-retry').onclick=()=>startMission(game?.missionId||selectedMissionId);$('#result-menu').onclick=showMenu;$('#result-next').onclick=()=>{const index=missions.findIndex(m=>m.id===game?.missionId);if(index>=0&&index+1<missions.length)startMission(missions[index+1].id)};renderCampaignMenu();

$('#training').onchange=renderCampaignMenu;$('#mission-search').oninput=renderCampaignMenu;

$('#close-building-catalog').onclick=()=>$('#building-catalog').hidden=true;$('#cancel-building').onclick=()=>placement?.cancel();$('#confirm-building').onclick=()=>placement?.confirm();

const factionHelp=document.createElement('p');factionHelp.className='help';$('#faction').closest('label').append(factionHelp);$('#faction').onchange=()=>{factionHelp.textContent=factions[$('#faction').value]?.description||'Facção de base com o catálogo completo de construções.'};$('#faction').onchange();

(async()=>{try{const params=new URLSearchParams(location.search),saved=localStorage.getItem('spaceinvaders_server');$('#server').value=params.get('server')||saved||'';$('#room').value=params.get('room')||localStorage.getItem('spaceinvaders_room')||crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase().padStart(6,'0');if(!$('#server').value){const cfg=await fetch('./runtime-config.json').then(r=>r.json()).catch(()=>null);if(cfg?.multiplayerServer)$('#server').value=cfg.multiplayerServer}if(!$('#server').value&&(/^(localhost|127\.0\.0\.1)$/.test(location.hostname)||location.port==='48777')){const info=await fetch('./server-info').then(r=>r.ok?r.json():null).catch(()=>null);if(info)$('#server').value=location.protocol==='https:'?'wss://'+location.host+'/multiplayer':'ws://'+location.host+'/multiplayer'}if(params.get('room')){$('#mode').value='pvp';renderCampaignMenu()}setTimeout(()=>$('#server').dispatchEvent(new Event('input')),0)}catch{}})();

$('#server').addEventListener('input',()=>{const a=$('#direct-server');try{const u=new URL($('#server').value);a.hidden=location.protocol!=='https:'||u.protocol!=='ws:';u.protocol='http:';u.pathname='/';u.search='room='+encodeURIComponent($('#room').value)+'&server='+encodeURIComponent($('#server').value);a.href=u.href}catch{a.hidden=true}});

const launchFromMenu=$('#start').onclick;const commandShell=mountCommandShell({missions,progress:()=>campaignProgress,canPlay:id=>canPlayMission(campaignProgress,id),selected:()=>selectedMissionId,pick:id=>{selectedMissionId=id;renderCampaignMenu()},launch:()=>launchFromMenu(),tap:()=>playSound('tap')});$('#start').onclick=()=>commandShell.askDifficulty();

function selectWorkers(){selection=new Set(units.filter(u=>u.alive&&u.team===myTeam()&&u.type==='worker').map(u=>u.id));selected=getEntity([...selection][0]);renderActions()}
function selectHero(){const hero=units.find(u=>u.alive&&u.team===myTeam()&&u.type==='hero');if(hero){select(hero);camTarget.set(hero.x,0,hero.z);updateCam()}}
function stopSelected(){if(!game||game.paused||game.over)return;for(const u of selectedUnits()){u.target=null;u.targetEnemy=null;u.hold=true}sendCommand({kind:'stop',ids:[...selection]})}
battleHud=mountBattleHud({state:()=>({active:!!game&&screen.style.display==='none',entities:[...units,...buildings].filter(e=>e.alive),selection,team:myTeam(),groups:controlGroups,faction:game?.faction}),label:e=>e.kind?buildingDefinition(e.kind,e.faction)?.label||e.kind:unitDefs[e.type]?.name||e.type,race:baseRace,select,hero:selectHero,focus:e=>{camTarget.set(e.x,0,e.z);updateCam()},group:(key,assign)=>{if(assign)controlGroups.set(key,[...selection]);else{selection=new Set((controlGroups.get(key)||[]).filter(id=>getEntity(id)?.team===myTeam()));selected=getEntity([...selection][0]);renderActions()}battleHud.update()},visible:e=>canTeamSee(e,myTeam()),project:e=>{if(!camera)return null;const p=new THREE.Vector3(e.x,heightAt(e.x,e.z)+(e.kind?7:e.type==='air'?6:4),e.z).project(camera);return{x:(p.x+1)*innerWidth/2,y:(1-p.y)*innerHeight/2,z:p.z}}});
$('#workers').onclick=selectWorkers;

function showOrderMarker(x,z,attack){const points=[];for(let i=0;i<4;i++){const a=i*Math.PI/2,dx=Math.cos(a),dz=Math.sin(a),px=-dz,pz=dx;points.push(dx*2,0,dz*2,dx*.6,0,dz*.6,dx*.6,0,dz*.6,dx*1.25+px*.6,0,dz*1.25+pz*.6,dx*.6,0,dz*.6,dx*1.25-px*.6,0,dz*1.25-pz*.6)}const o=new THREE.LineSegments(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(points,3)),new THREE.LineBasicMaterial({color:attack?0xff6554:0x49ff77,transparent:true,depthTest:false}));o.position.set(x,heightAt(x,z)+.25,z);o.renderOrder=5;o.raycast=()=>{};scene.add(o);fx.push({o,time:.8,fade:true})}


function panCameraAtEdges(dt){const enabled=!!game&&!game.paused&&!game.over&&screen.style.display==='none'&&!pointerStart&&$('#battle-options').hidden&&$('#battle-help').hidden&&$('#building-catalog').hidden&&!document.hidden;const delta=edgeScroll.delta(dt,camAngle,enabled);camTarget.x=clamp(camTarget.x+delta.x,-WORLD_RADIUS,WORLD_RADIUS);camTarget.z=clamp(camTarget.z+delta.z,-WORLD_RADIUS,WORLD_RADIUS)}
